#!/usr/bin/env python3
"""Round 10a: add go/rust/java/c++/c# templates to classic tasks."""
import json
from pathlib import Path

BASE = Path(__file__).resolve().parent.parent / 'data' / 'knowledge' / 'code_tasks'


def load(name):
    with open(BASE / name, encoding='utf-8') as fh:
        return json.load(fh)


def save(name, data):
    with open(BASE / name, 'w', encoding='utf-8') as fh:
        json.dump(data, fh, indent=2, ensure_ascii=False)
        fh.write('\n')


def task(data, tid):
    items = data.get('tasks', []) if isinstance(data, dict) else data
    for t in items:
        if t['task'] == tid:
            return t
    raise KeyError(tid)


def add(data, tid, langs):
    t = task(data, tid)
    t['languages'].update(langs)


d13 = load('13_python_utils.json')
d15 = load('15_ds_advanced.json')

