# ── lru_cache ──────────────────────────────────────────────────────────────
add(d15, 'lru_cache', {
    'go': 'package main\n\nimport "container/list"\n\ntype entry struct {\n    key   int\n    value int\n}\n\ntype LRUCache struct {\n    capacity int\n    items    map[int]*list.Element\n    order    *list.List\n}\n\nfunc NewLRUCache(capacity int) *LRUCache {\n    return &LRUCache{capacity: capacity, items: map[int]*list.Element{}, order: list.New()}\n}\n\nfunc (c *LRUCache) Get(key int) int {\n    el, ok := c.items[key]\n    if !ok {\n        return -1\n    }\n    c.order.MoveToFront(el)\n    return el.Value.(*entry).value\n}\n\nfunc (c *LRUCache) Put(key, value int) {\n    if el, ok := c.items[key]; ok {\n        el.Value.(*entry).value = value\n        c.order.MoveToFront(el)\n        return\n    }\n    el := c.order.PushFront(&entry{key: key, value: value})\n    c.items[key] = el\n    if len(c.items) > c.capacity {\n        last := c.order.Back()\n        c.order.Remove(last)\n        delete(c.items, last.Value.(*entry).key)\n    }\n}',
    'rust': 'use std::collections::HashMap;\n\n// Simplified O(1)-ish LRU: HashMap + recency re-insertion.\npub struct LRUCache {\n    capacity: usize,\n    items: HashMap<i32, i32>,\n    recency: Vec<i32>,   // front = most recent\n}\n\nimpl LRUCache {\n    pub fn new(capacity: i32) -> Self {\n        LRUCache { capacity: capacity as usize, items: HashMap::new(), recency: Vec::new() }\n    }\n\n    pub fn get(&mut self, key: i32) -> i32 {\n        match self.items.get(&key) {\n            Some(&v) => {\n                self.recency.retain(|&k| k != key);\n                self.recency.insert(0, key);\n                v\n            }\n            None => -1,\n        }\n    }\n\n    pub fn put(&mut self, key: i32, value: i32) {\n        if !self.items.contains_key(&key) {\n            self.recency.retain(|&k| k != key);\n            self.recency.insert(0, key);\n        }\n        self.items.insert(key, value);\n        if self.items.len() > self.capacity {\n            if let Some(oldest) = self.recency.pop() {\n                self.items.remove(&oldest);\n            }\n        }\n    }\n}',
    'java': 'import java.util.LinkedHashMap;\nimport java.util.Map;\n\npublic class LRUCache {\n    private final LinkedHashMap<Integer, Integer> map;\n\n    public LRUCache(int capacity) {\n        map = new LinkedHashMap<>(16, 0.75f, true) {   // accessOrder = true\n            @Override\n            protected boolean removeEldestEntry(Map.Entry<Integer, Integer> eldest) {\n                return size() > capacity;\n            }\n        };\n    }\n\n    public int get(int key) {\n        return map.getOrDefault(key, -1);\n    }\n\n    public void put(int key, int value) {\n        map.put(key, value);\n    }\n}',
    'c++': '#include <list>\n#include <unordered_map>\n\nclass LRUCache {\n    std::list<std::pair<int, int>> order;   // front = most recent\n    std::unordered_map<int, std::list<std::pair<int, int>>::iterator> items;\n    int capacity;\n\npublic:\n    LRUCache(int cap) : capacity(cap) {}\n\n    int get(int key) {\n        auto it = items.find(key);\n        if (it == items.end()) return -1;\n        order.splice(order.begin(), order, it->second);\n        return it->second->second;\n    }\n\n    void put(int key, int value) {\n        auto it = items.find(key);\n        if (it != items.end()) {\n            it->second->second = value;\n            order.splice(order.begin(), order, it->second);\n            return;\n        }\n        order.push_front({key, value});\n        items[key] = order.begin();\n        if (items.size() > capacity) {\n            items.erase(order.back().first);\n            order.pop_back();\n        }\n    }\n};',
    'c#': 'using System.Collections.Generic;\n\npublic class LRUCache\n{\n    private readonly int _capacity;\n    private readonly Dictionary<int, LinkedListNode<(int key, int value)>> _map = new();\n    private readonly LinkedList<(int key, int value)> _list = new();\n\n    public LRUCache(int capacity) => _capacity = capacity;\n\n    public int Get(int key)\n    {\n        if (!_map.TryGetValue(key, out var node)) return -1;\n        _list.Remove(node);\n        _list.AddFirst(node);\n        return node.Value.value;\n    }\n\n    public void Put(int key, int value)\n    {\n        if (_map.TryGetValue(key, out var node))\n        {\n            node.Value = (key, value);\n            _list.Remove(node);\n            _list.AddFirst(node);\n            return;\n        }\n        var newNode = _list.AddFirst((key, value));\n        _map[key] = newNode;\n        if (_map.Count > _capacity)\n        {\n            _map.Remove(_list.Last.Value.key);\n            _list.RemoveLast();\n        }\n    }\n}',
})

# ── merge_intervals ────────────────────────────────────────────────────────
add(d15, 'merge_intervals', {
    'go': 'package main\n\nimport "sort"\n\nfunc MergeIntervals(intervals [][]int) [][]int {\n    if len(intervals) == 0 {\n        return nil\n    }\n    sort.Slice(intervals, func(i, j int) bool { return intervals[i][0] < intervals[j][0] })\n    merged := [][]int{intervals[0]}\n    for _, iv := range intervals[1:] {\n        last := merged[len(merged)-1]\n        if iv[0] <= last[1] {\n            if iv[1] > last[1] {\n                last[1] = iv[1]\n            }\n        } else {\n            merged = append(merged, iv)\n        }\n    }\n    return merged\n}',
    'rust': 'pub fn merge_intervals(intervals: Vec<Vec<i32>>) -> Vec<Vec<i32>> {\n    if intervals.is_empty() {\n        return vec![];\n    }\n    let mut intervals = intervals;\n    intervals.sort_by_key(|iv| iv[0]);\n    let mut merged: Vec<Vec<i32>> = vec![intervals[0].clone()];\n    for iv in intervals.into_iter().skip(1) {\n        let last = merged.last_mut().unwrap();\n        if iv[0] <= last[1] {\n            last[1] = last[1].max(iv[1]);\n        } else {\n            merged.push(iv);\n        }\n    }\n    merged\n}',
    'java': 'import java.util.*;\n\npublic static int[][] mergeIntervals(int[][] intervals) {\n    if (intervals.length == 0) return new int[0][];\n    Arrays.sort(intervals, (a, b) -> a[0] - b[0]);\n    List<int[]> merged = new ArrayList<>();\n    merged.add(intervals[0]);\n    for (int i = 1; i < intervals.length; i++) {\n        int[] last = merged.get(merged.size() - 1);\n        if (intervals[i][0] <= last[1]) {\n            last[1] = Math.max(last[1], intervals[i][1]);\n        } else {\n            merged.add(intervals[i]);\n        }\n    }\n    return merged.toArray(new int[0][]);\n}',
    'c++': '#include <vector>\n#include <algorithm>\n\nstd::vector<std::vector<int>> mergeIntervals(std::vector<std::vector<int>> intervals) {\n    if (intervals.empty()) return {};\n    std::sort(intervals.begin(), intervals.end());\n    std::vector<std::vector<int>> merged;\n    for (const auto& iv : intervals) {\n        if (merged.empty() || iv[0] > merged.back()[1]) {\n            merged.push_back(iv);\n        } else {\n            merged.back()[1] = std::max(merged.back()[1], iv[1]);\n        }\n    }\n    return merged;\n}',
    'c#': 'public int[][] MergeIntervals(int[][] intervals)\n{\n    if (intervals.Length == 0) return Array.Empty<int[]>();\n    Array.Sort(intervals, (a, b) => a[0].CompareTo(b[0]));\n    var merged = new List<int[]> { intervals[0] };\n    foreach (var iv in intervals.Skip(1))\n    {\n        var last = merged[^1];\n        if (iv[0] <= last[1]) last[1] = Math.Max(last[1], iv[1]);\n        else merged.Add(iv);\n    }\n    return merged.ToArray();\n}',
})

# ── longest_common_prefix ──────────────────────────────────────────────────
add(d16 := load('16_strings_adv.json'), 'longest_common_prefix', {
    'go': 'package main\n\nimport "strings"\n\nfunc LongestCommonPrefix(strs []string) string {\n    if len(strs) == 0 {\n        return ""\n    }\n    prefix := strs[0]\n    for _, s := range strs[1:] {\n        for !strings.HasPrefix(s, prefix) {\n            prefix = prefix[:len(prefix)-1]\n            if prefix == "" {\n                return ""\n            }\n        }\n    }\n    return prefix\n}',
    'rust': 'pub fn longest_common_prefix(strs: &[String]) -> String {\n    if strs.is_empty() {\n        return String::new();\n    }\n    let mut prefix = strs[0].clone();\n    for s in &strs[1..] {\n        while !s.starts_with(&prefix) {\n            prefix.pop();\n            if prefix.is_empty() {\n                return prefix;\n            }\n        }\n    }\n    prefix\n}',
    'java': 'public static String longestCommonPrefix(String[] strs) {\n    if (strs.length == 0) return "";\n    String prefix = strs[0];\n    for (int i = 1; i < strs.length; i++) {\n        while (!strs[i].startsWith(prefix)) {\n            prefix = prefix.substring(0, prefix.length() - 1);\n            if (prefix.isEmpty()) return "";\n        }\n    }\n    return prefix;\n}',
    'c++': '#include <string>\n#include <vector>\n\nstd::string longestCommonPrefix(const std::vector<std::string>& strs) {\n    if (strs.empty()) return "";\n    std::string prefix = strs[0];\n    for (size_t i = 1; i < strs.size(); i++) {\n        while (strs[i].rfind(prefix, 0) != 0) {   // starts_with\n            prefix.pop_back();\n            if (prefix.empty()) return prefix;\n        }\n    }\n    return prefix;\n}',
    'c#': 'public static string LongestCommonPrefix(string[] strs)\n{\n    if (strs.Length == 0) return "";\n    string prefix = strs[0];\n    for (int i = 1; i < strs.Length; i++)\n    {\n        while (!strs[i].StartsWith(prefix))\n        {\n            prefix = prefix[..^1];\n            if (prefix.Length == 0) return prefix;\n        }\n    }\n    return prefix;\n}',
})
save('16_strings_adv.json', d16)

# ── edit_distance / reverse_words / count_vowels ───────────────────────────
add(d13, 'edit_distance', {
    'go': 'package main\n\nfunc EditDistance(a, b string) int {\n    m, n := len(a), len(b)\n    dp := make([][]int, m+1)\n    for i := range dp {\n        dp[i] = make([]int, n+1)\n        dp[i][0] = i\n    }\n    for j := 0; j <= n; j++ {\n        dp[0][j] = j\n    }\n    for i := 1; i <= m; i++ {\n        for j := 1; j <= n; j++ {\n            if a[i-1] == b[j-1] {\n                dp[i][j] = dp[i-1][j-1]\n            } else {\n                dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])\n            }\n        }\n    }\n    return dp[m][n]\n}\n\nfunc min(xs ...int) int {\n    best := xs[0]\n    for _, x := range xs[1:] {\n        if x < best {\n            best = x\n        }\n    }\n    return best\n}',
    'rust': 'pub fn edit_distance(a: &str, b: &str) -> usize {\n    let (m, n) = (a.len(), b.len());\n    let mut dp = vec![vec![0usize; n + 1]; m + 1];\n    for i in 0..=m { dp[i][0] = i; }\n    for j in 0..=n { dp[0][j] = j; }\n    for i in 1..=m {\n        for j in 1..=n {\n            dp[i][j] = if a.as_bytes()[i - 1] == b.as_bytes()[j - 1] {\n                dp[i - 1][j - 1]\n            } else {\n                1 + dp[i - 1][j].min(dp[i][j - 1]).min(dp[i - 1][j - 1])\n            };\n        }\n    }\n    dp[m][n]\n}',
    'java': 'public static int editDistance(String a, String b) {\n    int m = a.length(), n = b.length();\n    int[][] dp = new int[m + 1][n + 1];\n    for (int i = 0; i <= m; i++) dp[i][0] = i;\n    for (int j = 0; j <= n; j++) dp[0][j] = j;\n    for (int i = 1; i <= m; i++) {\n        for (int j = 1; j <= n; j++) {\n            if (a.charAt(i - 1) == b.charAt(j - 1)) {\n                dp[i][j] = dp[i - 1][j - 1];\n            } else {\n                dp[i][j] = 1 + Math.min(dp[i - 1][j], Math.min(dp[i][j - 1], dp[i - 1][j - 1]));\n            }\n        }\n    }\n    return dp[m][n];\n}',
    'c++': '#include <string>\n#include <vector>\n#include <algorithm>\n\nint editDistance(const std::string& a, const std::string& b) {\n    int m = a.size(), n = b.size();\n    std::vector<std::vector<int>> dp(m + 1, std::vector<int>(n + 1));\n    for (int i = 0; i <= m; i++) dp[i][0] = i;\n    for (int j = 0; j <= n; j++) dp[0][j] = j;\n    for (int i = 1; i <= m; i++) {\n        for (int j = 1; j <= n; j++) {\n            if (a[i - 1] == b[j - 1]) dp[i][j] = dp[i - 1][j - 1];\n            else dp[i][j] = 1 + std::min({dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]});\n        }\n    }\n    return dp[m][n];\n}',
    'c#': 'public static int EditDistance(string a, string b)\n{\n    int m = a.Length, n = b.Length;\n    var dp = new int[m + 1, n + 1];\n    for (int i = 0; i <= m; i++) dp[i, 0] = i;\n    for (int j = 0; j <= n; j++) dp[0, j] = j;\n    for (int i = 1; i <= m; i++)\n        for (int j = 1; j <= n; j++)\n            dp[i, j] = a[i - 1] == b[j - 1]\n                ? dp[i - 1, j - 1]\n                : 1 + Math.Min(dp[i - 1, j], Math.Min(dp[i, j - 1], dp[i - 1, j - 1]));\n    return dp[m, n];\n}',
})

add(d16, 'reverse_words', {
    'go': 'package main\n\nimport "strings"\n\nfunc ReverseWords(sentence string) string {\n    words := strings.Fields(sentence)\n    for i, j := 0, len(words)-1; i < j; i, j = i+1, j-1 {\n        words[i], words[j] = words[j], words[i]\n    }\n    return strings.Join(words, " ")\n}',
    'rust': 'pub fn reverse_words(sentence: &str) -> String {\n    sentence.split_whitespace().rev().collect::<Vec<_>>().join(" ")\n}',
    'java': 'public static String reverseWords(String sentence) {\n    String[] words = sentence.trim().split("\\\\s+");\n    Collections.reverse(Arrays.asList(words));\n    return String.join(" ", words);\n}',
    'c++': '#include <string>\n#include <sstream>\n#include <vector>\n\nstd::string reverseWords(const std::string& sentence) {\n    std::istringstream in(sentence);\n    std::vector<std::string> words;\n    std::string w;\n    while (in >> w) words.push_back(w);\n    std::reverse(words.begin(), words.end());\n    std::string out;\n    for (size_t i = 0; i < words.size(); i++) {\n        if (i) out += " ";\n        out += words[i];\n    }\n    return out;\n}',
    'c#': 'public static string ReverseWords(string sentence)\n{\n    var words = sentence.Split(\' \', StringSplitOptions.RemoveEmptyEntries);\n    Array.Reverse(words);\n    return string.Join(" ", words);\n}',
})

