add(d13, 'sliding_window_max', {
    'go': 'package main\n\nfunc SlidingWindowMax(nums []int, k int) []int {\n    dq := []int{}   // indices with decreasing values\n    out := []int{}\n    for i, n := range nums {\n        for len(dq) > 0 && nums[dq[len(dq)-1]] <= n {\n            dq = dq[:len(dq)-1]\n        }\n        dq = append(dq, i)\n        if dq[0] <= i-k {\n            dq = dq[1:]\n        }\n        if i >= k-1 {\n            out = append(out, nums[dq[0]])\n        }\n    }\n    return out\n}',
    'rust': 'use std::collections::VecDeque;\n\npub fn sliding_window_max(nums: &[i32], k: usize) -> Vec<i32> {\n    let mut dq: VecDeque<usize> = VecDeque::new();\n    let mut out = Vec::new();\n    for i in 0..nums.len() {\n        while let Some(&last) = dq.back() {\n            if nums[last] <= nums[i] { dq.pop_back(); } else { break; }\n        }\n        dq.push_back(i);\n        if dq[0] <= i.saturating_sub(k) { dq.pop_front(); }\n        if i + 1 >= k { out.push(nums[dq[0]]); }\n    }\n    out\n}',
    'java': 'import java.util.*;\n\npublic static int[] slidingWindowMax(int[] nums, int k) {\n    Deque<Integer> dq = new ArrayDeque<>();   // indices, decreasing values\n    List<Integer> out = new ArrayList<>();\n    for (int i = 0; i < nums.length; i++) {\n        while (!dq.isEmpty() && nums[dq.peekLast()] <= nums[i]) dq.pollLast();\n        dq.offerLast(i);\n        if (dq.peekFirst() <= i - k) dq.pollFirst();\n        if (i >= k - 1) out.add(nums[dq.peekFirst()]);\n    }\n    return out.stream().mapToInt(Integer::intValue).toArray();\n}',
    'c++': '#include <vector>\n#include <deque>\n\nstd::vector<int> slidingWindowMax(const std::vector<int>& nums, int k) {\n    std::deque<int> dq;   // indices with decreasing values\n    std::vector<int> out;\n    for (int i = 0; i < (int)nums.size(); i++) {\n        while (!dq.empty() && nums[dq.back()] <= nums[i]) dq.pop_back();\n        dq.push_back(i);\n        if (dq.front() <= i - k) dq.pop_front();\n        if (i >= k - 1) out.push_back(nums[dq.front()]);\n    }\n    return out;\n}',
    'c#': 'public static int[] SlidingWindowMax(int[] nums, int k)\n{\n    var dq = new LinkedList<int>();   // indices with decreasing values\n    var out = new List<int>();\n    for (int i = 0; i < nums.Length; i++)\n    {\n        while (dq.Count > 0 && nums[dq.Last()] <= nums[i]) dq.RemoveLast();\n        dq.AddLast(i);\n        if (dq.First() <= i - k) dq.RemoveFirst();\n        if (i >= k - 1) out.Add(nums[dq.First()]);\n    }\n    return out.ToArray();\n}',
})

add(d13, 'merge_sort', {
    'go': 'package main\n\nfunc MergeSort(items []int) []int {\n    if len(items) <= 1 {\n        return items\n    }\n    mid := len(items) / 2\n    left := MergeSort(items[:mid])\n    right := MergeSort(items[mid:])\n    out := make([]int, 0, len(items))\n    i, j := 0, 0\n    for i < len(left) && j < len(right) {\n        if left[i] <= right[j] {\n            out = append(out, left[i]); i++\n        } else {\n            out = append(out, right[j]); j++\n        }\n    }\n    out = append(out, left[i:]...)\n    out = append(out, right[j:]...)\n    return out\n}',
    'rust': 'pub fn merge_sort<T: Ord + Clone>(items: &[T]) -> Vec<T> {\n    if items.len() <= 1 {\n        return items.to_vec();\n    }\n    let mid = items.len() / 2;\n    let left = merge_sort(&items[..mid]);\n    let right = merge_sort(&items[mid..]);\n    let mut out = Vec::with_capacity(items.len());\n    let (mut i, mut j) = (0, 0);\n    while i < left.len() && j < right.len() {\n        if left[i] <= right[j] { out.push(left[i].clone()); i += 1; }\n        else { out.push(right[j].clone()); j += 1; }\n    }\n    out.extend_from_slice(&left[i..]);\n    out.extend_from_slice(&right[j..]);\n    out\n}',
    'java': 'public static List<Integer> mergeSort(List<Integer> items) {\n    if (items.size() <= 1) return items;\n    int mid = items.size() / 2;\n    List<Integer> left = mergeSort(new ArrayList<>(items.subList(0, mid)));\n    List<Integer> right = mergeSort(new ArrayList<>(items.subList(mid, items.size())));\n    List<Integer> out = new ArrayList<>();\n    int i = 0, j = 0;\n    while (i < left.size() && j < right.size()) {\n        if (left.get(i) <= right.get(j)) out.add(left.get(i++));\n        else out.add(right.get(j++));\n    }\n    while (i < left.size()) out.add(left.get(i++));\n    while (j < right.size()) out.add(right.get(j++));\n    return out;\n}',
    'c++': '#include <vector>\n\ntemplate <typename T>\nstd::vector<T> mergeSort(const std::vector<T>& items) {\n    if (items.size() <= 1) return items;\n    size_t mid = items.size() / 2;\n    auto left = mergeSort(std::vector<T>(items.begin(), items.begin() + mid));\n    auto right = mergeSort(std::vector<T>(items.begin() + mid, items.end()));\n    std::vector<T> out;\n    size_t i = 0, j = 0;\n    while (i < left.size() && j < right.size()) {\n        if (left[i] <= right[j]) out.push_back(left[i++]);\n        else out.push_back(right[j++]);\n    }\n    out.insert(out.end(), left.begin() + i, left.end());\n    out.insert(out.end(), right.begin() + j, right.end());\n    return out;\n}',
    'c#': 'public static List<T> MergeSort<T>(List<T> items) where T : IComparable<T>\n{\n    if (items.Count <= 1) return items;\n    int mid = items.Count / 2;\n    var left = MergeSort(items.GetRange(0, mid));\n    var right = MergeSort(items.GetRange(mid, items.Count - mid));\n    var out = new List<T>();\n    int i = 0, j = 0;\n    while (i < left.Count && j < right.Count)\n        out.Add(left[i].CompareTo(right[j]) <= 0 ? left[i++] : right[j++]);\n    while (i < left.Count) out.Add(left[i++]);\n    while (j < right.Count) out.Add(right[j++]);\n    return out;\n}',
})

