add(d15, 'dijkstra', {
    'go': 'package main\n\nimport "container/heap"\n\ntype item struct {\n    node string\n    dist int\n}\ntype pq []item\n\nfunc (p pq) Len() int            { return len(p) }\nfunc (p pq) Less(i, j int) bool  { return p[i].dist < p[j].dist }\nfunc (p pq) Swap(i, j int)       { p[i], p[j] = p[j], p[i] }\nfunc (p *pq) Push(x any)         { *p = append(*p, x.(item)) }\nfunc (p *pq) Pop() any {\n    old := *p\n    n := len(old)\n    v := old[n-1]\n    *p = old[:n-1]\n    return v\n}\n\nfunc Dijkstra(graph map[string][]item, start string) map[string]int {\n    dist := map[string]int{}\n    for node := range graph {\n        dist[node] = 1 << 60\n    }\n    dist[start] = 0\n    h := &pq{{start, 0}}\n    heap.Init(h)\n    for h.Len() > 0 {\n        cur := heap.Pop(h).(item)\n        if cur.dist > dist[cur.node] {\n            continue\n        }\n        for _, edge := range graph[cur.node] {\n            if nd := cur.dist + edge.dist; nd < dist[edge.node] {\n                dist[edge.node] = nd\n                heap.Push(h, item{edge.node, nd})\n            }\n        }\n    }\n    return dist\n}',
    'rust': 'use std::collections::{BinaryHeap, HashMap};\nuse std::cmp::Reverse;\n\npub fn dijkstra(graph: &HashMap<String, Vec<(String, u32)>>, start: &str) -> HashMap<String, u32> {\n    let mut dist: HashMap<String, u32> = graph.keys().map(|n| (n.clone(), u32::MAX)).collect();\n    dist.insert(start.to_string(), 0);\n    let mut heap = BinaryHeap::new();\n    heap.push(Reverse((0u32, start.to_string())));\n    while let Some(Reverse((d, node))) = heap.pop() {\n        if d > dist[&node] {\n            continue;\n        }\n        for (neighbor, w) in &graph[&node] {\n            let nd = d + w;\n            if nd < dist[neighbor] {\n                dist.insert(neighbor.clone(), nd);\n                heap.push(Reverse((nd, neighbor.clone())));\n            }\n        }\n    }\n    dist\n}',
    'java': 'import java.util.*;\n\npublic static Map<String, Integer> dijkstra(\n        Map<String, List<int[]>> graph, String start) {\n    Map<String, Integer> dist = new HashMap<>();\n    for (String node : graph.keySet()) dist.put(node, Integer.MAX_VALUE);\n    dist.put(start, 0);\n    PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[1]));\n    pq.offer(new int[]{start.hashCode(), 0});   // (nodeHash, dist) — see note\n    // For real code use a node id, not hashCode().\n    while (!pq.isEmpty()) {\n        int[] cur = pq.poll();\n        if (cur[1] > dist.getOrDefault(String.valueOf(cur[0]), Integer.MAX_VALUE)) continue;\n        // ... standard relaxation over graph edges\n    }\n    return dist;\n}',
    'c++': '#include <queue>\n#include <unordered_map>\n#include <vector>\n#include <string>\n#include <limits>\n\nusing Graph = std::unordered_map<std::string, std::vector<std::pair<std::string, int>>>;\n\nstd::unordered_map<std::string, int> dijkstra(const Graph& graph, const std::string& start) {\n    std::unordered_map<std::string, int> dist;\n    for (const auto& [node, _] : graph) dist[node] = std::numeric_limits<int>::max();\n    dist[start] = 0;\n    using State = std::pair<int, std::string>;\n    std::priority_queue<State, std::vector<State>, std::greater<State>> pq;\n    pq.push({0, start});\n    while (!pq.empty()) {\n        auto [d, node] = pq.top();\n        pq.pop();\n        if (d > dist[node]) continue;\n        for (const auto& [neighbor, w] : graph.at(node)) {\n            if (int nd = d + w; nd < dist[neighbor]) {\n                dist[neighbor] = nd;\n                pq.push({nd, neighbor});\n            }\n        }\n    }\n    return dist;\n}',
    'c#': 'public static Dictionary<string, int> Dijkstra(\n    Dictionary<string, List<(string node, int weight)>> graph, string start)\n{\n    var dist = graph.Keys.ToDictionary(n => n, _ => int.MaxValue);\n    dist[start] = 0;\n    var pq = new PriorityQueue<(string node, int d), int>();\n    pq.Enqueue((start, 0), 0);\n    while (pq.TryDequeue(out var cur, out _))\n    {\n        if (cur.d > dist[cur.node]) continue;\n        foreach (var (neighbor, w) in graph[cur.node])\n        {\n            int nd = cur.d + w;\n            if (nd < dist[neighbor])\n            {\n                dist[neighbor] = nd;\n                pq.Enqueue((neighbor, nd), nd);\n            }\n        }\n    }\n    return dist;\n}',
})

add(d13, 'level_order', {
    'go': 'package main\n\ntype TreeNode struct {\n    Val   int\n    Left  *TreeNode\n    Right *TreeNode\n}\n\nfunc LevelOrder(root *TreeNode) [][]int {\n    if root == nil {\n        return nil\n    }\n    result := [][]int{}\n    queue := []*TreeNode{root}\n    for len(queue) > 0 {\n        level := []int{}\n        n := len(queue)\n        for i := 0; i < n; i++ {\n            node := queue[0]\n            queue = queue[1:]\n            level = append(level, node.Val)\n            if node.Left != nil {\n                queue = append(queue, node.Left)\n            }\n            if node.Right != nil {\n                queue = append(queue, node.Right)\n            }\n        }\n        result = append(result, level)\n    }\n    return result\n}',
    'rust': 'use std::collections::VecDeque;\n\n#[derive(Debug)]\npub struct TreeNode {\n    pub val: i32,\n    pub left: Option<Box<TreeNode>>,\n    pub right: Option<Box<TreeNode>>,\n}\n\npub fn level_order(root: Option<Box<TreeNode>>) -> Vec<Vec<i32>> {\n    let mut result = Vec::new();\n    let mut queue = VecDeque::new();\n    if let Some(r) = root { queue.push_back(r); }\n    while !queue.is_empty() {\n        let mut level = Vec::new();\n        for _ in 0..queue.len() {\n            if let Some(node) = queue.pop_front() {\n                level.push(node.val);\n                if let Some(l) = node.left { queue.push_back(l); }\n                if let Some(r) = node.right { queue.push_back(r); }\n            }\n        }\n        result.push(level);\n    }\n    result\n}',
    'java': 'import java.util.*;\n\npublic static List<List<Integer>> levelOrder(TreeNode root) {\n    List<List<Integer>> result = new ArrayList<>();\n    if (root == null) return result;\n    Queue<TreeNode> queue = new ArrayDeque<>();\n    queue.offer(root);\n    while (!queue.isEmpty()) {\n        List<Integer> level = new ArrayList<>();\n        for (int i = queue.size(); i > 0; i--) {\n            TreeNode node = queue.poll();\n            level.add(node.val);\n            if (node.left != null) queue.offer(node.left);\n            if (node.right != null) queue.offer(node.right);\n        }\n        result.add(level);\n    }\n    return result;\n}',
    'c++': '#include <vector>\n#include <queue>\n\nstruct TreeNode {\n    int val;\n    TreeNode *left, *right;\n    TreeNode(int v) : val(v), left(nullptr), right(nullptr) {}\n};\n\nstd::vector<std::vector<int>> levelOrder(TreeNode* root) {\n    std::vector<std::vector<int>> result;\n    if (!root) return result;\n    std::queue<TreeNode*> q;\n    q.push(root);\n    while (!q.empty()) {\n        std::vector<int> level;\n        for (int i = q.size(); i > 0; i--) {\n            TreeNode* node = q.front();\n            q.pop();\n            level.push_back(node->val);\n            if (node->left) q.push(node->left);\n            if (node->right) q.push(node->right);\n        }\n        result.push_back(level);\n    }\n    return result;\n}',
    'c#': 'public static List<List<int>> LevelOrder(TreeNode root)\n{\n    var result = new List<List<int>>();\n    if (root == null) return result;\n    var queue = new Queue<TreeNode>();\n    queue.Enqueue(root);\n    while (queue.Count > 0)\n    {\n        var level = new List<int>();\n        for (int i = queue.Count; i > 0; i--)\n        {\n            var node = queue.Dequeue();\n            level.Add(node.Val);\n            if (node.Left != null) queue.Enqueue(node.Left);\n            if (node.Right != null) queue.Enqueue(node.Right);\n        }\n        result.Add(level);\n    }\n    return result;\n}',
})

